package remframework.geometry.discovery.configuration;

import remframework.geometry.discovery.*;
import remframework.geometry.discovery.experiment.FaceCompositionMode;
import remframework.geometry.discovery.graph.canonical.Canonicalizer;

import java.time.Instant;
import java.util.*;

/** Exact dual-triangulation state-space generation for cubic uniform spherical surfaces. */
public final class UniformSphericalFaceGenerator {
    public Outcome generate(ConfigurationRequest request,NormalizedGraphRequest normalized){long started=System.nanoTime();UniformSphericalSearchLimits limits=normalized.specializedSearchLimits();long deadline=started+limits.timeLimit().toNanos();Map<String,Long> pruning=new TreeMap<>();long examined=0,duplicates=0,completed=0;boolean limited=false;if(normalized.exactDegree()!=3||normalized.faceComposition().mode()!=FaceCompositionMode.UNIFORM_FACE_SIZE||normalized.expectedFaceCount()==null)return failed("Specialized generation currently requires exact primal K=3, F, and uniform m.",limits,started);int dualVertices=Math.toIntExact(normalized.expectedFaceCount());int dualDegree=normalized.faceComposition().commonFaceEdgeCount();if(dualVertices<4)return failed("A closed triangular dual requires at least four vertices.",limits,started);CombinatorialFaceComplex seed=seedTriangulation(dualVertices);CombinatorialSurfaceCanonicalizer canonicalizer=new CombinatorialSurfaceCanonicalizer();ArrayDeque<CombinatorialFaceComplex> frontier=new ArrayDeque<>();Set<String> seen=new HashSet<>();String seedCode=canonicalizer.canonicalize(seed).code();seen.add(seedCode);frontier.add(seed);List<Configuration> retained=new ArrayList<>();Set<String> primalCodes=new HashSet<>();while(!frontier.isEmpty()){if(System.nanoTime()>=deadline||examined>=limits.maximumPartialStates()||frontier.size()>limits.maximumFrontierStates()){limited=true;break;}CombinatorialFaceComplex dual=frontier.remove();examined++;if(dual.edges().stream().allMatch(edge->degree(dual,edge.firstNodeId())==dualDegree&&degree(dual,edge.secondNodeId())==dualDegree)){completed++;CombinatorialFaceComplex primal=dualize(dual);var validation=new CombinatorialSurfaceValidator().validate(primal,Math.toIntExact(normalized.expectedEdgeCount()),Math.toIntExact(normalized.expectedFaceCount()),normalized.exactDegree(),normalized.faceComposition().commonFaceEdgeCount(),normalized.surfaceTopologyAssumption().eulerCharacteristic());if(validation.valid()){var canonical=canonicalizer.canonicalize(primal);String graphLabel=primal.vertexCount()<=ConfigurationGenerator.MAX_EXHAUSTIVE_N?new Canonicalizer().canonicalLabel(primal.vertexCount(),validation.edges()):canonical.code();if(!primalCodes.add(graphLabel)){duplicates++;pruning.merge("DUPLICATE_ISOMORPH",1L,Long::sum);}else if(retained.size()<limits.maximumCompletedConfigurations())retained.add(configuration(request,normalized,primal,validation.edges(),graphLabel,canonical,retained.size()+1,!limited));else{limited=true;break;}}else for(String failure:validation.failures())pruning.merge(failure,1L,Long::sum);}
            for(CombinatorialFaceComplex next:flips(dual,pruning)){String code=canonicalizer.canonicalize(next).code();if(seen.add(code))frontier.add(next);else{duplicates++;pruning.merge("CANONICAL_PARTIAL_DUPLICATE",1L,Long::sum);}}
        }GenerationCompleteness completeness=limited?GenerationCompleteness.INCOMPLETE_SEARCH_LIMIT_REACHED:GenerationCompleteness.COMPLETE_FOR_SELECTED_PARAMETER_CLASS;String explanation=limited?"The canonical dual-triangulation frontier reached a configured search limit; retained results are incomplete.":"The connected canonical edge-flip state space of dual triangulations was exhausted for the selected parameter class.";GenerationDiagnostics diagnostics=new GenerationDiagnostics(GenerationStrategy.UNIFORM_SPHERICAL_FACE_GENERATION,"1",ConstructionMethod.DUAL_TRIANGULATED_SURFACE,completeness,examined,pruning.values().stream().mapToLong(Long::longValue).sum(),completed,duplicates,retained.size(),pruning,limits,explanation);return new Outcome(retained,diagnostics,(System.nanoTime()-started)/1_000_000);}
    private static Configuration configuration(ConfigurationRequest request,NormalizedGraphRequest normalized,CombinatorialFaceComplex primal,List<DiscoveryConnection> edges,String label,CombinatorialSurfaceCanonicalizer.Result canonical,int index,boolean complete){String hash=shortHash(label);var diagnostic=GeometryConfigurationDiagnostic.info(GeometryConfigurationStage.COMPLETE,GeometryConfigurationStatusCode.ELIGIBLE_FOR_GEOMETRY_TEST,"Uniform spherical topology generated","A coordinate-free primal face complex passed independent closed-manifold validation after dual construction.");return new Configuration(new ConfigurationId("cfg-"+hash),primal.vertexCount(),normalized.exactDegree(),edges,null,label,hash,canonical.automorphismCount(),canonical.vertexTransitive()?GraphSymmetryClassification.HIGHLY_SYMMETRIC:canonical.automorphismCount()>1?GraphSymmetryClassification.SYMMETRIC:GraphSymmetryClassification.ASYMMETRIC,true,index,GenerationStrategy.UNIFORM_SPHERICAL_FACE_GENERATION.name(),complete,GeometryConfigurationStatus.of(diagnostic),List.of(diagnostic),Instant.now(),Map.of("constructionMethod",ConstructionMethod.DUAL_TRIANGULATED_SURFACE.name(),"combinatorialFaces",primal.encode(),"strategyVersion","1"));}
    private static CombinatorialFaceComplex seedTriangulation(int vertices){List<List<Integer>> faces=new ArrayList<>(List.of(List.of(0,2,1),List.of(0,1,3),List.of(1,2,3),List.of(2,0,3)));for(int vertex=4;vertex<vertices;vertex++){List<Integer> face=faces.removeFirst();int a=face.get(0),b=face.get(1),c=face.get(2);faces.add(List.of(a,b,vertex));faces.add(List.of(b,c,vertex));faces.add(List.of(c,a,vertex));}return new CombinatorialFaceComplex(vertices,faces);}
    private static List<CombinatorialFaceComplex> flips(CombinatorialFaceComplex surface,Map<String,Long> pruning){Map<Long,List<Integer>> incident=new TreeMap<>();for(int fi=0;fi<surface.faces().size();fi++){List<Integer> face=surface.faces().get(fi);for(int i=0;i<3;i++){DiscoveryConnection edge=new DiscoveryConnection(face.get(i),face.get((i+1)%3));incident.computeIfAbsent(edge.undirectedKey(),ignored->new ArrayList<>()).add(fi);}}Set<Long> existing=incident.keySet();List<CombinatorialFaceComplex> result=new ArrayList<>();for(var entry:incident.entrySet()){if(entry.getValue().size()!=2){pruning.merge("EDGE_FACE_INCIDENCE_FAILED",1L,Long::sum);continue;}int first=entry.getValue().get(0),second=entry.getValue().get(1);List<Integer>a=surface.faces().get(first),b=surface.faces().get(second);int u=(int)(entry.getKey()>>32),v=(int)(long)entry.getKey();int c=opposite(a,u,v),d=opposite(b,u,v);if(c==d||existing.contains(new DiscoveryConnection(c,d).undirectedKey())){pruning.merge("NON_FLIPPABLE_EDGE",1L,Long::sum);continue;}List<Integer> orientedA=orientEdge(a,u,v),orientedB=orientEdge(b,v,u);if(orientedA==null||orientedB==null){orientedA=orientEdge(a,v,u);orientedB=orientEdge(b,u,v);if(orientedA==null||orientedB==null){pruning.merge("INVALID_LOCAL_MANIFOLD",1L,Long::sum);continue;}int swap=u;u=v;v=swap;c=orientedA.get(2);d=orientedB.get(2);}else{c=orientedA.get(2);d=orientedB.get(2);}List<List<Integer>> faces=new ArrayList<>(surface.faces());faces.set(first,List.of(c,d,v));faces.set(second,List.of(d,c,u));result.add(new CombinatorialFaceComplex(surface.vertexCount(),faces));}return result;}
    private static int opposite(List<Integer> face,int a,int b){return face.stream().filter(v->v!=a&&v!=b).findFirst().orElseThrow();}
    private static List<Integer> orientEdge(List<Integer> face,int a,int b){for(int i=0;i<3;i++)if(face.get(i)==a&&face.get((i+1)%3)==b)return List.of(a,b,face.get((i+2)%3));return null;}
    private static int degree(CombinatorialFaceComplex surface,int vertex){Set<Integer> neighbors=new HashSet<>();for(DiscoveryConnection edge:surface.edges())if(edge.firstNodeId()==vertex)neighbors.add(edge.secondNodeId());else if(edge.secondNodeId()==vertex)neighbors.add(edge.firstNodeId());return neighbors.size();}
    private static CombinatorialFaceComplex dualize(CombinatorialFaceComplex dual){List<List<Integer>> primalFaces=new ArrayList<>();for(int vertex=0;vertex<dual.vertexCount();vertex++){List<Integer> incident=new ArrayList<>();for(int fi=0;fi<dual.faces().size();fi++)if(dual.faces().get(fi).contains(vertex))incident.add(fi);Map<Integer,Set<Integer>> adjacency=new HashMap<>();incident.forEach(face->adjacency.put(face,new TreeSet<>()));for(int i:incident)for(int j:incident)if(i<j&&sharedEdgeAtVertex(dual.faces().get(i),dual.faces().get(j),vertex)) {adjacency.get(i).add(j);adjacency.get(j).add(i);}List<Integer> cycle=new ArrayList<>();int start=incident.stream().min(Integer::compare).orElseThrow(),previous=-1,current=start;do{cycle.add(current);List<Integer> next=adjacency.get(current).stream().toList();int selected=next.get(0)==previous?next.get(1):next.get(0);previous=current;current=selected;}while(current!=start&&cycle.size()<=incident.size());primalFaces.add(cycle);}return new CombinatorialFaceComplex(dual.faces().size(),orientConsistently(primalFaces));}
    private static boolean sharedEdgeAtVertex(List<Integer>a,List<Integer>b,int vertex){Set<Integer> shared=new HashSet<>(a);shared.retainAll(b);return shared.size()==2&&shared.contains(vertex);}
    private static List<List<Integer>> orientConsistently(List<List<Integer>> faces){List<List<Integer>> result=new ArrayList<>();for(List<Integer> face:faces)result.add(new ArrayList<>(face));Map<Long,List<Integer>> incident=new HashMap<>();for(int fi=0;fi<result.size();fi++)for(int i=0;i<result.get(fi).size();i++)incident.computeIfAbsent(new DiscoveryConnection(result.get(fi).get(i),result.get(fi).get((i+1)%result.get(fi).size())).undirectedKey(),ignored->new ArrayList<>()).add(fi);boolean[] done=new boolean[result.size()];ArrayDeque<Integer> q=new ArrayDeque<>();done[0]=true;q.add(0);while(!q.isEmpty()){int current=q.remove();List<Integer> face=result.get(current);for(int i=0;i<face.size();i++){int a=face.get(i),b=face.get((i+1)%face.size());for(int other:incident.get(new DiscoveryConnection(a,b).undirectedKey()))if(!done[other]){if(hasDirectedEdge(result.get(other),a,b))Collections.reverse(result.get(other));done[other]=true;q.add(other);}}}return result.stream().map(List::copyOf).toList();}
    private static boolean hasDirectedEdge(List<Integer>face,int a,int b){for(int i=0;i<face.size();i++)if(face.get(i)==a&&face.get((i+1)%face.size())==b)return true;return false;}
    private static Outcome failed(String explanation,UniformSphericalSearchLimits limits,long started){return new Outcome(List.of(),new GenerationDiagnostics(GenerationStrategy.UNIFORM_SPHERICAL_FACE_GENERATION,"1",ConstructionMethod.DUAL_TRIANGULATED_SURFACE,GenerationCompleteness.FAILED_GENERATION,0,0,0,0,0,Map.of(),limits,explanation),(System.nanoTime()-started)/1_000_000);}
    private static String shortHash(String value){try{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8))).substring(0,12);}catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}}
    public record Outcome(List<Configuration> configurations,GenerationDiagnostics diagnostics,long elapsedMilliseconds){public Outcome{configurations=List.copyOf(configurations);}}
}
